function proceduralScene(s){
 const threats=[
 {title:'FUNKLOCH',text:`Das Signal zerfällt in digitales Rauschen. ${s.name} ist irgendwo in ${pick(locations)}. Ein paar Sekunden nur – aber in dieser Stadt können Sekunden ein ganzes Leben kosten.`,opts:[['Zum nächsten Relaispunkt lotsen.','trust',5],['Batterie sparen. Funkstille, bis es sicher ist.','energy',6],['Notruf auf allen Kanälen absetzen.','evidence',0]]},
 {title:'DIE STADT BEISST',text:`„${pick(['Der Boden ist weggebrochen.','Hier riecht alles nach Ozon.','Ich glaube, jemand folgt mir.','Meine Hände zittern. Verdammt.','Da ist ein Licht, aber es bewegt sich.'])}“\n\n${s.name} hat kaum Zeit. Du hörst ${s.weather} draußen gegen das Blech peitschen.`,opts:[['Langsam atmen. Einen Schritt nach dem anderen.','morale',7],['Schneller werden. Nicht stehen bleiben.','health',-7],['Warte. Ich prüfe erst den Kartenfeed.','evidence',0]]},
 {title:'EIN FREMDER',text:`Ein Fremder bietet ${s.name} Hilfe an. Er sagt, er kenne einen sicheren Weg durch ${pick(locations)}. Doch sein Ausweis ist abgelaufen, und seine Stimme klingt zu ruhig.`,opts:[['Ihm eine Chance geben. Gemeinsam seid ihr stärker.','trust',6],['Abstand halten und den Weg selbst prüfen.','energy',-3],['Weitergehen. Keine Zeit für Fremde.','cold',-3]]},
 {title:'LETZTE RESSOURCEN',text:`Der Rucksack ist fast leer. ${s.name} findet ${pick(['eine halbvolle Wasserflasche','einen alten Medpatch','einen leeren Akkupack','eine Dose Bohnen','ein paar Meter Kupferdraht'])}. Die nächste Etappe wird nicht leichter.`,opts:[['Sofort verwenden. Der Körper braucht es.','health',9],['Für den Notfall aufheben.','inventory',0],['Mit einem anderen Überlebenden teilen.','morale',8]]},
 {title:'SCHATTEN IM NEBEL',text:`Bewegung im Nebel. ${s.name} geht in Deckung. Ein Suchscheinwerfer schwenkt über die Straße, bleibt stehen – direkt über ${pos} Versteck.`,opts:[['Nicht rühren. Ruhig bleiben.','hide',0],['Ablenkung werfen und lossprinten.','run',0],['Den Sender stören, ich helfe von hier.','evidence',0]]},
 {title:'EINE STIMME AUS DER VERGANGENHEIT',text:`Eine Nachricht kommt rein. Eine vertraute Stimme, archiviert und verzerrt: „${s.name}… komm nach Hause.“\n\n${s.name} sagt nichts. Vielleicht ist es eine Falle. Vielleicht auch die einzige Hoffnung.`,opts:[['Antworten. Manchmal ist Hoffnung alles.','morale',9],['Nach der Quelle suchen. Das könnte wichtig sein.','evidence',0],['Das ist nicht echt. Weiter.','trust',-4]]}
 ];
 let q=pick(threats), options=q.opts.map(([label,type,val])=>({label,type,val}));
 return{text:`// ${q.title}\n\n${q.text}`,options,prompt:'DEINE ENTSCHEIDUNG HAT FOLGEN'}
}
function sandboxScene(s,idx){
 const enemy=s.sandbox.enemy||'Rogue drone',weapon=s.sandbox.weapon||'Shock baton';
 const events=[
 {text:`SANDBOX // ${s.name} betritt ${s.location}. ${s.weather} verschluckt die Neonreklamen. Eine ${enemy} versperrt den einzigen Ausgang. Deine Ausrüstung: ${weapon}.\n\nHier gibt es keine vorgeschriebene Geschichte. Nur die Welt, die du dir gebaut hast.`,opts:[['Angreifen – direkt und kompromisslos.','fight',0],['Gegner analysieren. Vielleicht hat er eine Schwachstelle.','evidence',0],['Deckung suchen und einen Umweg finden.','hide',0]]},
 {text:`Die Straße endet an einem prozedural generierten Sperrgebiet. Dahinter: ein Vorratsdepot und ein Funksignal. ${s.name} hat die Wahl, aber die Zeit läuft.`,opts:[['Zum Depot. Vorräte sind wichtiger.','health',0],['Dem Signal folgen. Vielleicht wartet Hilfe.','trust',5],['Das Gebiet umgehen. Kein unnötiges Risiko.','energy',3]]},
 {text:`Ein Händler tritt aus einer Gasse. Er bietet eine Verbesserung für deine ${weapon} – gegen Energie, die ${s.name} kaum noch hat.`,opts:[['Tauschen. Stärker werden, um zu überleben.','power',0],['Ablehnen. Jede Ressource zählt.','energy',4],['Verhandeln. Vielleicht gibt es einen besseren Deal.','trust',4]]},
 {text:`Die ${enemy} hat Verstärkung gerufen. ${s.name} kann den Generator sabotieren, fliehen oder das Risiko eingehen und kämpfen. Die Sandbox passt sich jeder Entscheidung an.`,opts:[['Generator sabotieren und die Gegner blenden.','evidence',0],['Kampf! Ich habe dich mit ${weapon} ausgerüstet.','fight',0],['Rückzug. Eine neue Route generieren.','run',0]]}
 ];let e=events[idx%events.length];return{text:e.text.replaceAll('${weapon}',weapon),options:e.opts.map(([label,type,val])=>({label:label.replaceAll('${weapon}',weapon),type,val})),prompt:'SANDBOX-AKTION WÄHLEN'}
}
function choose(i){if(!state||!state.alive)return;const buttons=$$('#choices .choice');if(buttons[i])buttons[i].disabled=true;const scene=makeScene(state),o=scene.options[i];if(!o)return;sound('choice');const s=state;s.decisions++;s.turn++;s.history.push({day:s.days,chapter:chapters[Math.min(s.chapter,6)],text:$('#storyText').innerText,choice:o.label});if(s.history.length>100)s.history.shift();
 applyChoice(o);if(!s.alive){renderScene();setTimeout(()=>endRun(false),250);return}
 if(s.mode==='campaign'){
  if(s.turn%5===0&&s.chapter<6){s.chapter++;s.location=pick(locations);s.weather=pick(weather);s.days+=1+Math.floor(Math.random()*2);if(s.chapter===3)notify('Kapitelwechsel // neue Koordinaten empfangen');}
  if(s.turn>=35){renderScene();setTimeout(()=>endRun(true),300);return}
 }else{s.days+=Math.random()<.42?1:0;if(s.turn%8===0){s.location=pick(locations);s.weather=pick(weather)}}
 if(s.health<=0||s.morale<=0){s.alive=false;renderScene();setTimeout(()=>endRun(false),250);return}
 renderScene(s.turn%4===0);save();
}
function applyChoice(o){const s=state;switch(o.type){
 case'trust':s.trust=clamp(s.trust+(o.val||4));s.morale=clamp(s.morale+2);break;
 case'morale':s.morale=clamp(s.morale+(o.val||6));s.trust=clamp(s.trust+2);break;
 case'cold':s.morale=clamp(s.morale+(o.val||-5));s.trust=clamp(s.trust-4);break;
 case'health':s.health=clamp(s.health+(o.val||-5));s.energy=clamp(s.energy-3);break;
 case'energy':s.energy=clamp(s.energy+(o.val||-5));if(!o.val)s.health=clamp(s.health-4);break;
 case'evidence':s.evidence++;s.energy=clamp(s.energy-3);s.inventory.includes('Datensplitter')||s.inventory.push('Datensplitter');s.trust=clamp(s.trust+1);break;
 case'risk':if(Math.random()<.55){s.health=clamp(s.health-15);s.morale=clamp(s.morale-7);toast('Das Risiko ging schief.');}else{s.energy=clamp(s.energy+8);s.trust=clamp(s.trust+4);toast('Knapp geschafft. Weiter.')}break;
 case'run':if(Math.random()<.7){s.energy=clamp(s.energy-13);s.health=clamp(s.health-5);toast('Du entkommst. Aber zu welchem Preis?')}else{s.health=clamp(s.health-22);toast('Abgefangen. Du bist verletzt.')}break;
 case'loud':if(Math.random()<.58){s.health=clamp(s.health-19);s.morale=clamp(s.morale-5);toast('Der Lärm hat etwas angelockt.')}else{s.energy=clamp(s.energy-6);toast('Die Tür gibt nach.')}break;
 case'hide':s.energy=clamp(s.energy-4);if(Math.random()<.27)s.health=clamp(s.health-10);else s.trust=clamp(s.trust+2);break;
 case'fast':s.health=clamp(s.health-8);s.energy=clamp(s.energy+3);break;
 case'bold':if(Math.random()<.5){s.health=clamp(s.health-12);s.morale=clamp(s.morale+5)}else{s.trust=clamp(s.trust+6);s.morale=clamp(s.morale+3)}break;
 case'power':if(s.powerups>0){s.powerups--;s.health=clamp(s.health+18);s.energy=clamp(s.energy+15);s.morale=clamp(s.morale+5);toast('Notfallsender aktiviert. Werte stabilisiert.')}else{s.energy=clamp(s.energy-5);toast('Kein Powerup verfügbar.')}break;
 case'inventory':if(s.inventory.length<5)s.inventory.push(pick(['Medpatch','Wasser','Ersatzakku','Draht','Schlüsselkarte']));s.energy=clamp(s.energy+2);break;
 case'fight':if(Math.random()<.66){s.health=clamp(s.health-11);s.morale=clamp(s.morale+4);s.inventory.push('Drohnenkern');toast('Gegner ausgeschaltet. Beute gesichert.')}else{s.health=clamp(s.health-25);s.morale=clamp(s.morale-8);toast('Der Kampf war härter als gedacht.')}break;
 case'sacrifice':if(s.evidence>0){s.evidence=Math.max(0,s.evidence-1);s.health=clamp(s.health-9);s.morale=clamp(s.morale+7)}else{s.trust=clamp(s.trust-4);s.health=clamp(s.health-12)}break;
 default:s.energy=clamp(s.energy-2);s.trust=clamp(s.trust+2)
 }
 s.energy=clamp(s.energy-1);if(s.health<=0||s.morale<=0)s.alive=false;
}
function usePowerup(){if(!state)return;if(state.powerups<=0){toast('Keine Powerups mehr vorhanden.');sound();return}state.powerups--;state.health=clamp(state.health+14);state.energy=clamp(state.energy+12);state.morale=clamp(state.morale+4);sound('choice');toast('✦ NOTFALLSTIMULANS // Werte stabilisiert');renderScene();save()}
function endRun(survived){if(!state)return;const s=state;s.alive=survived;const score=weightedScore();if(s.mode==='campaign'){data.scores.push({name:s.name,score,survived,days:s.days,difficulty:s.difficulty,date:new Date().toISOString()});data.scores.sort((a,b)=>b.score-a.score);data.scores=data.scores.slice(0,20);if(survived)data.survivors++;data.best=Math.max(data.best,score);save()}sound(survived?'choice':'alert');
 const title=survived?'DU HAST ÜBERLEBT.':'DAS SIGNAL VERSTUMMT.';const summary=survived?`${s.name} hat es aus Neo Berlin geschafft. ${s.days} Tage lang hast du zugehört, beraten und nicht aufgegeben. ${s.evidence?`${s.evidence} Beweisstücke wurden gerettet. `:''}Die Stadt wacht auf. Diesmal hat jemand den Morgen gesehen.`:`Der letzte Funkspruch von ${s.name} kam aus ${s.location}. Dann nur noch Rauschen. Deine Entscheidungen haben Spuren hinterlassen – aber diesmal hat die Stadt gewonnen.`;
 $('#modal').innerHTML=`<button class="modal-close" onclick="closeModal()">×</button><div class="ending"><div class="section-label">${survived?'ÜBERTRAGUNG BEENDET':'SIGNAL VERLOREN'}</div><h2>${title}</h2><p>${summary}</p><div class="control-preview">ÜBERLEBENSZEIT ${s.days} TAGE &nbsp;·&nbsp; ENTSCHEIDUNGEN ${s.decisions}<br>ENDSTAND ${score.toLocaleString('de-DE')} &nbsp;·&nbsp; SCHWIERIGKEIT ${s.difficulty.toUpperCase()}</div><div class="modal-actions" style="justify-content:center"><button class="primary" onclick="closeModal();beginCampaign()">NOCH EINMAL <span>↗</span></button><button class="secondary" onclick="closeModal();showScreen('menu')">ZUM HAUPTMENÜ <span>↗</span></button></div></div>`;openModal();state=null;
}

