--- index.html
+++ index.html
@@ -6,5 +6,36 @@
 @media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important}}@keyframes pulse{50%{opacity:.3}}@keyframes rain{to{transform:translateY(25%)}}@keyframes breath{50%{transform:translateY(-5px)}}@keyframes float{50%{transform:translateY(-7px)}}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes fade{from{opacity:0}to{opacity:1}}
 </style></head><body><div class="noise"></div><div class="app"><header class="top"><div class="brand">SIGNAL<span style="color:#718085">//</span><b>LOST</b></div><div><span class="live">SIGNAL AKTIV</span> <button class="icon" aria-label="Optionen" onclick="openSettings()">⚙</button></div></header>
 <main id="menu" class="screen active"><section class="hero"><div class="copy"><div class="eyebrow">EIN TEXT-RPG · CYBERPUNK 2091</div><h1>SIGNAL<span>//LOST</span></h1><p class="desc">Jemand ist dort draußen. <strong>Allein. Verletzt. Ohne Ausweg.</strong><br>Das Einzige, was noch durch die Stille kommt, ist deine Stimme. Was du jetzt sagst, entscheidet, ob ein Mensch den Morgen erlebt.</p><div class="actions"><button class="primary" onclick="beginCampaign()">KAMPAGNE STARTEN <span>↗</span></button><button id="resumeBtn" class="secondary" style="display:none" onclick="resumeCampaign()">KAMPAGNE FORTSETZEN <span>↗</span></button><button class="secondary" onclick="openSandbox()">SANDBOX // FREIES SPIEL <span>↗</span></button></div><div class="foot">7 AKTE · 40+ FUNKSPRUCH-EREIGNISSE · DEINE ENTSCHEIDUNGEN ZÄHLEN</div></div><div class="art"><div class="frame"><div class="moon"></div><div class="haze"></div><div class="city"><i class="tower"></i><i class="tower"></i><i class="tower"></i><i class="tower"></i><i class="tower"></i><i class="tower"></i><i class="tower"></i></div><div class="rain"></div><div class="person"><div class="hood"></div><div class="head"></div><div class="body"></div><div class="coat"></div><i class="leg l"></i><i class="leg r"></i></div><div class="signal"><b>◉ EINGEHENDER FUNK</b><p>„Bitte… ist da draußen jemand?“</p><small>ANOMALIE IM NETZ · 23:47</small></div><div class="caption">NEO BERLIN <b>·</b> SEKTOR 09 <b>·</b> 2091</div></div><div class="menu-stats">KAMPAGNEN <b id="menuRuns">0</b><br>HÖCHSTER SCORE <b id="menuScore">—</b><br>ÜBERLEBENSQUOTE <b id="menuRate">—</b></div></div></section><footer class="footer"><span>© BANDOS7 · MADE IN DEUTSCHLAND</span><span>OFFLINE SPIELBAR · LOKALER FORTSCHRITT</span></footer></main>
 <main id="game" class="screen"><div class="game"><div class="gamehead"><div><div class="game-title">◉ EINGEHENDE ÜBERTRAGUNG <span id="modeTag"></span></div><div class="chapter" id="chapterTitle">—</div></div><div class="day" id="dayLabel">TAG 01 · 23:47</div></div><div class="stats" id="stats"></div><article class="transmission"><div class="txmeta"><span id="speaker">UNBEKANNTE STIMME</span><span class="time" id="txTime">23:47 · SIGNAL SCHWACH</span></div><div class="story" id="storyText"></div></article><div class="choice-label" id="choicesLabel">WIE ANTWORTEST DU?</div><div class="choices" id="choices"></div><div class="chips" id="inventory"></div><div class="tools"><button class="small" onclick="usePowerup()">✦ POWERUP <span id="powerCount">0</span></button><button class="small" onclick="openJournal()">⌁ FUNKJOURNAL</button><button class="small" onclick="openBoard()">◎ RANKING</button><button class="small" onclick="openSettings()">⚙ OPTIONEN</button><button class="small" onclick="confirmExit()">↩ MENÜ</button></div></div></main>
-<div class="overlay" id="overlay" onclick="overlayBackdrop(event)"><section class="modal" id="modal"></section></div><div class="toast" id="toast" role="status"></div>
+<div class="overlay" id="overlay" onclick="overlayBackdrop(event)"><section class="modal" id="modal"></section></div><div class="toast" id="toast" role="status"></div><script>
+'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='signallost_v1';
+const defaults={difficulty:'normal',controls:'pulse',touch:'one',graphics:'high',sound:true,vibration:false,volume:55};let settings={...defaults,...JSON.parse(localStorage.getItem(KEY+'_settings')||'{}')},data=JSON.parse(localStorage.getItem(KEY)||'{"runs":0,"best":0,"scores":[],"survivors":0}'),state=null,audio=null,timer=null,swipeStart=null;
+const chapters=['DAS ERSTE SIGNAL','UNTER DER STADT','GLAS UND GIFT','DIE LEERE ZONE','FREMDE FREQUENZEN','LETZTER AUSWEG','MORGENROT'],names={f:['Mara Voss','Nika Brandt','Yuna Keller','Lea Novak','Sora Weiss'],m:['Jona Falk','Elias Kern','Noah Richter','Milan Wolf','Kai Berger']},locations=['Kreuzberg-9','U-Bahn-Station Oranien','Spreebogen','Schwarzer Markt','Sektor Null','Astra-Klinik','Kanal 17','Dachgärten von Mitte','Neonhafen','Ringbahn-Tunnel','Archiv der Stimmen','Glasviertel'],callsigns=['KOMET','NACHTFALKE','ECHO-7','LANTERN','KABELSALAT','GRAUWOLF','MOTTE','STERNENSTAUB'],weather=['Säureregen','Smog','Stromsturm','dichter Nebel','Ascheregen','kalter Niesel'];
+const pick=a=>a[Math.floor(Math.random()*a.length)],clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
+function save(){localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(KEY+'_settings',JSON.stringify(settings));if(state?.mode==='campaign')localStorage.setItem(KEY+'_run',JSON.stringify(state));updateMenu()}
+function updateMenu(){ $('#menuRuns').textContent=data.runs;$('#menuScore').textContent=data.best?data.best.toLocaleString('de-DE'):'—';$('#menuRate').textContent=data.runs?Math.round(data.survivors/data.runs*100)+'%':'—';$('#resumeBtn').style.display=localStorage.getItem(KEY+'_run')?'flex':'none'}
+function screen(id){$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));window.scrollTo(0,0)}function msg(t){const x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>x.classList.remove('show'),2500)}
+function sound(type='tap'){if(!settings.sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain(),f=type==='choice'?440:type==='alert'?660:280;o.connect(g);g.connect(audio.destination);o.type=type==='alert'?'triangle':'sine';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.65,audio.currentTime+.12);g.gain.setValueAtTime(settings.volume/1000,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.16);o.start();o.stop(audio.currentTime+.17)}catch(e){}}
+function notify(t){sound('alert');if(settings.vibration&&navigator.vibrate)navigator.vibrate([70,40,70]);msg('◉ FUNK EINGEGANGEN · '+t);if(document.visibilityState==='visible'&&'Notification'in window&&Notification.permission==='granted')new Notification('SIGNAL//LOST',{body:t,tag:'signallost'})}
+function beginCampaign(){sound();newRun('campaign')}function resumeCampaign(){try{state=JSON.parse(localStorage.getItem(KEY+'_run'));screen('game');render(true)}catch(e){localStorage.removeItem(KEY+'_run');beginCampaign()}}
+function newRun(mode='campaign',cfg={}){let gender=Math.random()<.5?'f':'m',d=cfg.difficulty||settings.difficulty,base={easy:[100,100,72,58],normal:[86,82,60,48],hard:[72,68,48,38]}[d]||[86,82,60,48];state={mode,gender,name:cfg.name||pick(names[gender]),callsign:pick(callsigns),location:cfg.location||pick(locations),weather:pick(weather),difficulty:d,health:+cfg.health||base[0],energy:+cfg.energy||base[1],morale:base[2],trust:base[3],days:1,chapter:0,turn:0,decisions:0,evidence:0,alive:true,powerups:2,inventory:['Cracked commlink','Water ×1'],history:[],seed:Math.random().toString(36).slice(2,8),sandbox:cfg};if(mode==='sandbox'){state.health=Number(cfg.health||90);state.energy=Number(cfg.energy||85);state.inventory=[cfg.weapon||'Shock baton',cfg.enemy||'Rogue drone']}if(mode==='campaign')data.runs++;screen('game');save();render(true)}
+function person(){return state.gender==='f'?'Sie':'Er'}function poss(){return state.gender==='f'?'ihr':'sein'}
+function makeScene(s){if(s.mode==='sandbox')return sandboxScene(s);if(s.turn>=16)return procedural(s);let p=person().toLowerCase(),pos=poss(),n=s.name,l=s.location;const scenes=[
+[`„Hallo? Kannst du mich hören? Mein Name ist ${n}. Ich sitze in einem Wartungsschacht unter ${l}. Überall Rauch. Mein Bein… ich glaube, ich kann nicht mehr richtig laufen.“\n\nDas Signal bricht ab, kommt wieder. Im Hintergrund heult etwas Metallisches durch die Dunkelheit.`,[['Sag ${n}, dass du da bist. Bitte ${p} um den genauen Standort.','trust',5],['Frag zuerst nach ${pos} Verletzung. Ruhig bleiben, Schritt für Schritt.','morale',5],['Keine Antwort. Das könnte eine Falle sein.','cold',-4]]],
+[`„Da ist ein Schild. Wartungsschacht C-4. Ich sehe ein rotes Licht am Ende des Tunnels… und höre Schritte. Nicht menschliche.“\n\n${p} Atem geht schnell. Deine Verbindung rauscht bedrohlich.`,[['Licht aus. Nicht bewegen, bis die Schritte vorbei sind.','energy',3],['Wirf etwas in die andere Richtung. Lenke es ab.','risk',0],['Renn. Jetzt. Keine Zeit verlieren.','run',0]]],
+[`Der Kanal knackt. „Ich hab einen alten Erste-Hilfe-Kasten gefunden. Aber die Tür ist verkeilt. Ich könnte sie aufbrechen… oder das Schloss mit dem Draht hier knacken.“\n\n${n} klingt erschöpft. Jede Minute zählt.`,[['Schloss knacken. Langsam und leise.','energy',2],['Tür aufbrechen. Scheiß auf den Lärm.','loud',0],['Erst Wunde versorgen. Dann weitersehen.','health',0]]],
+[`„Da ist ein Terminal. Zeigt einen Evakuierungsplan, aber das Ding will einen Zugangscode. Ich könnte das System hacken, wenn du mich durch die Schritte führst.“\n\nAuf der anderen Seite der Leitung hörst du ${pos} leises Fluchen.`,[['Hilf beim Hacken. Vielleicht findest du einen sicheren Weg.','evidence',0],['Ignorier das Terminal. Der direkte Weg ist schneller.','fast',0],['Frag, was ${p} wirklich aufhält.','trust',6]]],
+[`Ein schriller Alarm schneidet durch den Kanal. „Scheiße! Die Sicherheitsdrohnen sind wach. Ich bin hinter einer Wartungsklappe, aber die hält nicht ewig.“\n\nDu kannst den Strom im Sektor kappen – wenn ${n} den Sicherungskasten erreicht.`,[['Strom kappen. Ich leite dich durch den Verteiler.','energy',0],['Verstecken bleiben. Kein Risiko eingehen.','hide',0],['Ablenkung über den Lautsprecher. Auf mein Zeichen.','trust',0]]],
+[`„Ich hab was gefunden. Ein Datenchip mit Namen drauf. Leute, die hier verschwunden sind. Einer davon… mein Bruder.“\n\nDie Stimme wird leiser. Das hier ist mehr als ein Fluchtweg.`,[['Chip sichern. Diese Geschichte verdient Antworten.','evidence',0],['Lass ihn liegen. Dein Leben geht vor.','health',4],['Versprich, dass ihr die Wahrheit rausfindet.','morale',8]]],
+[`Draußen. Endlich. Aber der Regen brennt auf der Haut. Ein Transporter steht am Ende der Straße. Daneben: zwei Gestalten in Konzernuniform.\n\n„Ich kann ihnen nicht trauen. Was soll ich tun?“`,[['Deckung suchen und die Lage beobachten.','trust',0],['Direkt auf sie zugehen. Hände sichtbar.','bold',0],['Zum Kanal. Der ist gefährlich, aber leer.','risk',0]]],
+[`„Der Kanal führt zum alten Umspannwerk. Mein Bein wird schlimmer. Ich hab noch eine Dosis Schmerzmittel, aber die könnte ich später brauchen.“\n\nDie Stille danach sagt alles. ${n} wartet auf deine Entscheidung.`,[['Nimm die Dosis jetzt. Du musst weitergehen können.','health',0],['Heb sie auf. Zähne zusammenbeißen.','energy',0],['Ich bleibe bei dir. Wir machen das in deinem Tempo.','morale',10]]],
+[`Im Funk: „Überlebende, hier spricht die Freie Zone. Wir können euch rausholen. Nennt uns euren Standort.“\n\n${n} flüstert: „Das könnte echt sein. Oder eine Falle.“`,[['Mit verschlüsseltem Code antworten.','evidence',0],['Gar nicht antworten. Weiter zum Umspannwerk.','trust',-2],['Den Code senden. Es ist unsere beste Chance.','risk',0]]],
+[`Im Umspannwerk brennt noch Licht. Ein alter Aufzug führt nach oben – oder der Wartungstunnel unter der Anlage. Über euch patrouilliert ein bewaffneter Trupp.\n\n„Letzte Chance umzukehren“, sagt ${n}.`,[['Aufzug nehmen. Schnell und unberechenbar.','energy',0],['Tunnel. Lang, aber ungesehen.','health',2],['Es gibt kein Zurück. Du entscheidest.','trust',5]]],
+[`„Ich hab das Signal der Freien Zone gefunden. Aber sie wollen, dass ich den Chip übergebe. Alle Namen, alle Beweise – weg.“\n\n${n} schweigt einen Moment. „Was ist wichtiger? Die Wahrheit oder… wir?“`,[['Den Chip behalten. Ohne Wahrheit ändert sich nichts.','evidence',0],['Den Chip übergeben. Ein Leben ist wichtiger.','morale',7],['Eine Kopie machen. Beides, wenn wir schnell sind.','energy',0]]],
+[`Ein Schuss. Dann noch einer. „Sie haben uns gefunden. Ich kann die Treppe hoch – oder das alte Seilbahnnetz nehmen. Das Kabel sieht verdammt morsch aus.“\n\n${n} atmet hörbar. Diesmal gibt es keine sichere Wahl.`,[['Treppe. Deckung suchen, jeden Schritt prüfen.','health',0],['Seilbahn. Risiko ist besser als sicherer Tod.','bold',0],['Kampf vermeiden. Zurück in den Tunnel.','hide',0]]],
+[`„Oben. Ich sehe den Himmel. Er ist… orange. Alles brennt.“\n\nVor ${n} liegt ein Dachgarten und dahinter die Extraktionszone. Ein letztes Hindernis: eine verriegelte Schleuse und ein System, das eine manuelle Überbrückung braucht.`,[['Mit dem Datenchip die Schleuse öffnen.','evidence',0],['Notstrom nutzen. Du hast genug Energie gesammelt.','energy',0],['Schleuse aufbrechen. Jetzt ist keine Zeit.','health',0]]],
+[`Das Rettungssignal antwortet. „Wir sehen euch. Noch 400 Meter bis zum Dach.“\n\nDann Stille. Dann: „${n}? Sag irgendwas. Bitte.“ Der Sturm frisst das letzte bisschen Verbindung.`,[['Durchhalten. Immer weiterreden. Ich bin hier.','morale',0],['Signal mit dem Notfallsender verstärken.','power',0],['Zum Licht laufen – egal, wer dort wartet.','bold',0]]],
+[`Letzte Nacht. Letzte Entscheidung. ${n} steht am Rand des Dachs. Unter euch flackert Neo Berlin. Der Rettungstransporter nähert sich – aber eine Gestalt tritt aus dem Schatten.\n\n„Die Konzernpolizei. Sie will den Chip. Was soll ich tun?“`,[['Chip werfen. ${n} soll zum Transporter rennen.','sacrifice',0],['Beweise senden, dann im Chaos verschwinden.','evidence',0],['Sich ergeben. Vielleicht verhandeln.','trust',0]]],
+[`Der Morgen kommt in einem schmutzigen Rosa über die Dächer. ${n} ist nur noch eine Armlänge von der rettenden Luke entfernt.\n\n„Ich kann nicht mehr.“ Die Stimme ist kaum mehr als ein Flüstern. „Sag mir, dass es sich gelohnt hat.“`,[['Es hat sich gelohnt. Nur noch ein Schritt.','morale',12],['Denk an den Morgen. Du schaffst das.','trust',8],['Schweigen. Die Entscheidung liegt bei ${n}.','cold',-2]]]
+ ];let [text,opts]=scenes[s.turn%16];text=text.replaceAll('${n}',n).replaceAll('${p}',p).replaceAll('${pos}',pos).replaceAll('${l}',l);return{text,options:opts.map(([label,type,val])=>({label:label.replaceAll('${n}',n).replaceAll('${p}',p).replaceAll('${pos}',pos),type,val})),prompt:s.turn===15?'WAS SAGST DU?':'WIE ANTWORTEST DU?'}
