32: [`Im Funk: „Überlebende, hier spricht die Freie Zone. Wir können euch rausholen. Nennt uns euren Standort.“\n\n${n} flüstert: „Das könnte echt sein. Oder eine Falle.“`,[['Mit verschlüsseltem Code antworten.','evidence',0],['Gar nicht antworten. Weiter zum Umspannwerk.','trust',-2],['Den Code senden. Es ist unsere beste Chance.','risk',0]]],
33: [`Im Umspannwerk brennt noch Licht. Ein alter Aufzug führt nach oben – oder der Wartungstunnel unter der Anlage. Über euch patrouilliert ein bewaffneter Trupp.\n\n„Letzte Chance umzukehren“, sagt ${n}.`,[['Aufzug nehmen. Schnell und unberechenbar.','energy',0],['Tunnel. Lang, aber ungesehen.','health',2],['Es gibt kein Zurück. Du entscheidest.','trust',5]]],
34: [`„Ich hab das Signal der Freien Zone gefunden. Aber sie wollen, dass ich den Chip übergebe. Alle Namen, alle Beweise – weg.“\n\n${n} schweigt einen Moment. „Was ist wichtiger? Die Wahrheit oder… wir?“`,[['Den Chip behalten. Ohne Wahrheit ändert sich nichts.','evidence',0],['Den Chip übergeben. Ein Leben ist wichtiger.','morale',7],['Eine Kopie machen. Beides, wenn wir schnell sind.','energy',0]]],
35: [`Ein Schuss. Dann noch einer. „Sie haben uns gefunden. Ich kann die Treppe hoch – oder das alte Seilbahnnetz nehmen. Das Kabel sieht verdammt morsch aus.“\n\n${n} atmet hörbar. Diesmal gibt es keine sichere Wahl.`,[['Treppe. Deckung suchen, jeden Schritt prüfen.','health',0],['Seilbahn. Risiko ist besser als sicherer Tod.','bold',0],['Kampf vermeiden. Zurück in den Tunnel.','hide',0]]],
36: [`„Oben. Ich sehe den Himmel. Er ist… orange. Alles brennt.“\n\nVor ${n} liegt ein Dachgarten und dahinter die Extraktionszone. Ein letztes Hindernis: eine verriegelte Schleuse und ein System, das eine manuelle Überbrückung braucht.`,[['Mit dem Datenchip die Schleuse öffnen.','evidence',0],['Notstrom nutzen. Du hast genug Energie gesammelt.','energy',0],['Schleuse aufbrechen. Jetzt ist keine Zeit.','health',0]]],
37: [`Das Rettungssignal antwortet. „Wir sehen euch. Noch 400 Meter bis zum Dach.“\n\nDann Stille. Dann: „${n}? Sag irgendwas. Bitte.“ Der Sturm frisst das letzte bisschen Verbindung.`,[['Durchhalten. Immer weiterreden. Ich bin hier.','morale',0],['Signal mit dem Notfallsender verstärken.','power',0],['Zum Licht laufen – egal, wer dort wartet.','bold',0]]],
38: [`Letzte Nacht. Letzte Entscheidung. ${n} steht am Rand des Dachs. Unter euch flackert Neo Berlin. Der Rettungstransporter nähert sich – aber eine Gestalt tritt aus dem Schatten.\n\n„Die Konzernpolizei. Sie will den Chip. Was soll ich tun?“`,[['Chip werfen. ${n} soll zum Transporter rennen.','sacrifice',0],['Beweise senden, dann im Chaos verschwinden.','evidence',0],['Sich ergeben. Vielleicht verhandeln.','trust',0]]],
39: [`Der Morgen kommt in einem schmutzigen Rosa über die Dächer. ${n} ist nur noch eine Armlänge von der rettenden Luke entfernt.\n\n„Ich kann nicht mehr.“ Die Stimme ist kaum mehr als ein Flüstern. „Sag mir, dass es sich gelohnt hat.“`,[['Es hat sich gelohnt. Nur noch ein Schritt.','morale',12],['Denk an den Morgen. Du schaffst das.','trust',8],['Schweigen. Die Entscheidung liegt bei ${n}.','cold',-2]]]
40:  ];let [text,opts]=scenes[s.turn%16];text=text.replaceAll('${n}',n).replaceAll('${p}',p).replaceAll('${pos}',pos).replaceAll('${l}',l);return{text,options:opts.map(([label,type,val])=>({label:label.replaceAll('${n}',n).replaceAll('${p}',p).replaceAll('${pos}',pos),type,val})),prompt:s.turn===15?'WAS SAGST DU?':'WIE ANTWORTEST DU?'}
41: }

