function procedural(s){const p=person().toLowerCase(),n=s.name,l=pick(locations),w=pick(weather),events=[
 [`${w} legt sich wie eine zweite Haut über ${l}. ${n} findet einen verlassenen Sanitätskiosk. Das Licht darin flackert, doch die Tür steht offen. „Ich höre etwas hinter dem Vorhang.“`,[['Leise nachsehen und den Raum sichern.','energy',3],['Erst die Vorräte nehmen, dann weiter.','health',4],['Raus da. Kein Risiko.','trust',-1]]],
 [`Ein fremdes Signal überlagert euren Kanal: „Komm allein zur Brücke.“ ${n} erkennt die Stimme nicht. Auf der Karte blinkt ein Umweg durch einen überfluteten Tunnel.`,[['Mit einem Codewort die Identität prüfen.','evidence',1],['Brücke beobachten, bevor du antwortest.','trust',4],['Tunnel nehmen und Funkstille halten.','energy',-3]]],
 [`Ein flackerndes Werbeholo zeigt ein lächelndes Gesicht. Dahinter steckt ein funktionierender Notfallterminal. ${n} kann es erreichen, aber die Gegend ist offen.`,[['Schnell den Terminal nutzen.','evidence',1],['Deckung geben, während ${n} arbeitet.','morale',6],['Nicht stehen bleiben.','health',-3]]],
 [`Ein Schwarm kleiner Wartungsdrohnen zieht durch die Gasse. Eine trägt einen blinkenden Akku. „Wenn ich den erwische, kann ich unser Gerät laden.“`,[['Akku holen, aber langsam.','energy',8],['Ablenken und lossprinten.','health',-5],['Weitergehen. Vielleicht lauert noch mehr.','trust',2]]],
 [`Unter einer Treppe sitzt ein Kind mit einer zerbrochenen Maske. ${n} bleibt stehen. Der Fluchtweg liegt gleich dahinter, doch aus der Ferne kommen Stimmen.`,[['Maske teilen und kurz helfen.','morale',9],['Weg beschreiben und Vorräte dalassen.','trust',5],['Weiter. Ihr könnt niemanden retten.','morale',-7]]],
 [`Der Funk fängt eine verschlüsselte Durchsage der Freien Zone auf. Es klingt nach einer Warnung vor einem einstürzenden Übergang.`,[['Warnung prüfen und einen Umweg suchen.','health',3],['Signalquelle lokalisieren.','evidence',1],['Abkürzung nehmen. Zeit ist knapp.','risk',0]]],
 [`Ein Schott fällt hinter ${n} ins Schloss. Auf der anderen Seite tickt ein alter Generator. „Ich kann ihn überbrücken, aber dann wird es laut.“`,[['Generator überbrücken, bereit zum Rennen.','energy',-5],['Schott manuell öffnen. Keine Elektronik.','health',-4],['Ruhe bewahren und nach einem Hebel suchen.','morale',4]]],
 [`Für einen Augenblick ist die Leitung klar. ${n} erzählt von einem Morgen vor dem Blackout – Kaffee, ein offenes Fenster, ganz normale Geräusche.`,[['Zuhören. Lass ${n} den Moment behalten.','morale',8],['Frag nach dem Weg zum sicheren Dach.','evidence',1],['Erinnere daran, weiterzugehen.','energy',4]]]
 ];let [text,raw]=events[(s.turn-16)%events.length];text=text.replaceAll('${n}',n).replaceAll('${p}',p).replaceAll('${pos}',poss()).replaceAll('${l}',l);return{text,options:raw.map(([label,type,val])=>({label:label.replaceAll('${n}',n),type,val})),prompt:'WAS TUST DU?'} }
function sandboxScene(s){let n=s.name||'Runner',enemy=s.sandbox?.enemy||'Rogue drone',weapon=s.sandbox?.weapon||'Shock baton',l=s.location;let events=[
 [`Im Sektor ${l} taucht ein ${enemy} aus dem Rauch auf. Dein ${weapon} ist bereit, aber die enge Gasse bietet kaum Deckung.`,[['Deckung suchen und Schwachstelle beobachten.','energy',5],['Mit dem ${weapon} direkt angreifen.','risk',0],['Ablenken und vorbeischleichen.','trust',4]]],
 [`${n}, der Kanal rauscht. Vor dir liegen ein versiegelter Vorratscontainer und frische Spuren. Der ${enemy} ist noch in der Nähe.`,[['Container vorsichtig öffnen.','health',7],['Spuren lesen und den Gegner umgehen.','evidence',1],['Schnell zugreifen.','risk',0]]],
