function showModal(html){$('#modal').innerHTML=html;$('#overlay').classList.add('open');document.body.style.overflow='hidden'}function closeModal(){$('#overlay').classList.remove('open');document.body.style.overflow=''}function overlayBackdrop(e){if(e.target.id==='overlay')closeModal()}
function openSettings(){sound();showModal(`<button class="close" onclick="closeModal()" aria-label="Schließen">×</button><div class="label">SYSTEMKONFIGURATION</div><h2>Optionen</h2><p class="modalcopy">Passe Darstellung, Ton und Bedienung an. Einstellungen werden lokal gespeichert.</p><div class="row"><label>Schwierigkeit<small>Beeinflusst Startwerte und Risiko</small></label><select id="setDifficulty"><option value="easy">Story · leicht</option><option value="normal">Normal</option><option value="hard">Überleben · schwer</option></select></div><div class="row"><label>Steuerung<small>Farbakzent für dein Funk-Interface</small></label><select id="setControls"><option value="pulse">Pulse · Mint</option><option value="ember">Ember · Orange</option><option value="violet">Violet · Violett</option><option value="ice">Ice · Blau</option><option value="rose">Rose · Pink</option><option value="amber">Amber · Gold</option></select></div><div class="row"><label>Touch-Bedienung<small>Für einhändige oder beidhändige Nutzung</small></label><select id="setTouch"><option value="one">Ein Finger</option><option value="two">Zwei Finger</option></select></div><div class="row"><label>Grafik<small>Effekte für dein Gerät</small></label><select id="setGraphics"><option value="high">Dynamisch</option><option value="low">Reduziert</option></select></div><div class="row"><label>Soundeffekte</label><input id="setSound" type="checkbox"></div><div class="row"><label>Vibration bei Funk</label><input id="setVibe" type="checkbox"></div><div class="row"><label>Lautstärke</label><input id="setVolume" type="range" min="0" max="100"></div><div class="modalactions"><button class="primary" onclick="saveSettings()">ÜBERNEHMEN <span>✓</span></button><button class="secondary" onclick="closeModal()">ABBRECHEN</button><button class="secondary" onclick="requestNotifications()">FUNK-MELDUNGEN AKTIVIEREN</button></div>`);$('#setDifficulty').value=settings.difficulty;$('#setControls').value=settings.controls;$('#setTouch').value=settings.touch;$('#setGraphics').value=settings.graphics;$('#setSound').checked=settings.sound;$('#setVibe').checked=settings.vibration;$('#setVolume').value=settings.volume}
function saveSettings(){settings={...settings,difficulty:$('#setDifficulty').value,controls:$('#setControls').value,touch:$('#setTouch').value,graphics:$('#setGraphics').value,sound:$('#setSound').checked,vibration:$('#setVibe').checked,volume:+$('#setVolume').value};let colors={pulse:'#83f0d0',ember:'#f3bd72',violet:'#b6a0ff',ice:'#83c8f0',rose:'#ff6486',amber:'#ffc65f'};document.documentElement.style.setProperty('--cyan',colors[settings.controls]||colors.pulse);if(settings.graphics==='low')document.documentElement.style.setProperty('--fx','0');localStorage.setItem(KEY+'_settings',JSON.stringify(settings));closeModal();msg('Einstellungen gespeichert.')}
